steps.run:
$pf = ${env:ProgramFiles(x86)}
$wrong = @()
if (Test-Path -LiteralPath 'C:\ProgramData\RelayTrap') { $wrong += 'RelayTrap folder still there' }
if (Test-Path -LiteralPath 'C:\Windows\Temp\sckit-test') { $wrong += 'sckit-test still there' }
if (Get-ScheduledTask -TaskName 'TrapWatch' -ErrorAction SilentlyContinue) { $wrong += 'TrapWatch task still there' }
if ((Get-ItemProperty -Path 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Run').PSObject.Properties['RelayTrapLiteAlert']) { $wrong += 'Run value still there' }
if (Get-Service -Name 'ScreenConnect Client (aaaabbbbccccdddd)' -ErrorAction SilentlyContinue) { $wrong += 'other instance service still there' }
if (Test-Path -LiteralPath (Join-Path $pf 'ScreenConnect Client (aaaabbbbccccdddd)')) { $wrong += 'other instance folder still there' }
if (-not (Get-Service -Name 'ScreenConnect Client (0123456789abcdef)' -ErrorAction SilentlyContinue)) { $wrong += 'OUR service was removed' }
if (-not (Test-Path -LiteralPath (Join-Path $pf 'ScreenConnect Client (0123456789abcdef)\ScreenConnect.ClientService.exe'))) { $wrong += 'OUR folder was removed' }
$log = @(Get-ChildItem -LiteralPath 'C:\ProgramData\TechCollective\SCHunt' -Filter 'findings-*.txt' -ErrorAction SilentlyContinue)
if ($log.Count -eq 0) { $wrong += 'no evidence log' }
else {
    $saved = Get-Content -Raw -LiteralPath $log[0].FullName
    foreach ($s in @('TrapWatch', 'RelayTrapLiteAlert', 'relay.example.net')) { if (-not $saved.Contains($s)) { $wrong += "evidence log does not mention $s" } }
}
if (@(Get-ChildItem -LiteralPath 'C:\ProgramData\TechCollective\SCHunt' -Filter 'evidence-*.zip' -ErrorAction SilentlyContinue).Count -eq 0) { $wrong += 'no evidence zip' }
if ($wrong.Count) { 'WRONG: ' + ($wrong -join '; '); exit 1 }
'all planted items gone, our client kept, evidence saved'
